param([string]$Root=(Join-Path $env:LOCALAPPDATA 'G6\RabbitMQ\g5-onboarding'))
$ErrorActionPreference='Stop';$vault=Get-Content -Raw -LiteralPath (Join-Path $Root 'admin-vault.dpapi.json')|ConvertFrom-Json;$backup=[IO.File]::ReadAllBytes((Join-Path $Root 'packages\g5_equipo.admin-backup.g5enc'));$package=[IO.File]::ReadAllBytes((Join-Path $Root 'packages\g5_equipo.g5pkg'))
if($backup.Length-lt 53-or[Text.Encoding]::ASCII.GetString($backup,0,5)-cne'G5BK1'){throw 'Administrative backup format is invalid.'};$salt=[byte[]]$backup[5..20];$iterations=[BitConverter]::ToInt32($backup,21);$nonce=[byte[]]$backup[25..36];if($iterations-lt 600000-or$iterations-gt 2000000){throw 'Administrative backup KDF parameters are unsupported.'};$tagAt=$backup.Length-16;$cipher=[byte[]]$backup[37..($tagAt-1)];$tag=[byte[]]$backup[$tagAt..($backup.Length-1)];$header=[byte[]]$backup[0..36];$secure=ConvertTo-SecureString $vault.ProtectedAdminBackupPassword;$password=[Net.NetworkCredential]::new('', $secure).Password;$key=[Security.Cryptography.Rfc2898DeriveBytes]::Pbkdf2($password,$salt,$iterations,[Security.Cryptography.HashAlgorithmName]::SHA256,32);$plain=[byte[]]::new($cipher.Length);$aes=[Security.Cryptography.AesGcm]::new($key,16)
try{$aes.Decrypt($nonce,$cipher,$tag,$plain,$header);$expected=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($package));$actual=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($plain));if($actual-cne$expected){throw 'Administrative backup integrity mismatch.'};Write-Output 'PASS: administrative backup decrypts in memory and matches the encrypted G5 team package.'}finally{$password=$null;$secure.Dispose();$aes.Dispose();foreach($buffer in @($backup,$package,$cipher,$tag,$header,$key,$plain)){if($buffer -is [byte[]]){[Security.Cryptography.CryptographicOperations]::ZeroMemory($buffer)}}}
